import { buildPollutionEvent } from './pollution-event-builder.js';import { advectPoint } from './transport-simulator.js';
export function compilePollutionLens({signals=[],eventMeta={},transport=null}={}){const event=buildPollutionEvent(signals,eventMeta);if(event.state==='UNAVAILABLE')return{event,transport:{allowed:false,reason:'NO_EVENT'}};let movement={allowed:false,reason:'NOT_REQUESTED'};if(transport)movement=advectPoint(transport);return{event,transport:movement,display:{truthLegend:event.truthLegend,sourceAttribution:event.sourceAttribution.status,transportLabel:movement.allowed?'MODELLED':null}};}
